import { apiClient } from './client';

export interface Customer {
  id: string;
  code: string;
  fullName: string;
  phone: string | null;
  dateOfBirth: string | null;
  address: string | null;
  createdAt: string;
}

/** Fields the form edits. The code is generated by the backend; `null` clears a date of birth. */
export interface CustomerInput {
  fullName: string;
  phone?: string;
  dateOfBirth?: string | null;
  address?: string;
}

export const customersApi = {
  list: (search?: string) =>
    apiClient.get<Customer[]>('/customers', { params: { search } }).then((r) => r.data),

  get: (id: string) => apiClient.get<Customer>(`/customers/${id}`).then((r) => r.data),

  create: (input: CustomerInput) =>
    apiClient.post<Customer>('/customers', input).then((r) => r.data),

  update: (id: string, input: Partial<CustomerInput>) =>
    apiClient.patch<Customer>(`/customers/${id}`, input).then((r) => r.data),
};
